mapper.select:
SELECT IFNULL(afbt.form_name,afb.form_name) form_name, afb.* FROM app_form_base afb LEFT JOIN app_form_base_tenant afbt ON afbt.form_id = afb.id WHERE afb.module_id = #{pageDTO.moduleId}
AND afb.form_name LIKE CONCAT('%',#{pageDTO.formName},'%')
AND afb.form_type = #{pageDTO.formType}
